with base as (select *, cast(amount as int) amount_int, coalesce(method, 'DIRECT') method_clean from payments where paid_at > timestamp '2023-07-02 17:00:00' and method is distinct from 'cash'), gaps as (select *, case when lag(paid_at) over (partition by order_id order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by order_id order by paid_at, id) + interval 90 days then 1 else 0 end as session_start_flag from base), islands as (select *, sum(session_start_flag) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as session_no from gaps) select date_trunc('year', paid_at) as year_start, max(paid_at) as last_paid_at, avg(amount_int) as avg_amount_int, round(avg(amount), 2) as avg_amount, count(distinct method) as distinct_methods, round(avg(amount), 2) as avg_amount_2 from islands group by cube (date_trunc('year', paid_at));
